<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$key=trim((string)($_POST['section_key']??''));$title=trim((string)($_POST['title']??''));$image=trim((string)($_POST['image_url']??''));if($key===''||$title==='')throw new RuntimeException('Bölmə açarı və başlıq tələb olunur.');if($image!==''&&!filter_var($image,FILTER_VALIDATE_URL))throw new RuntimeException('Şəkil linki düzgün deyil.');$args=[$key,$title,trim((string)($_POST['content']??'')),$image?:null,(int)($_POST['sort_order']??0),isset($_POST['is_published'])?1:0];if($id){$q=$pdo->prepare('UPDATE portfolio SET section_key=?,title=?,content=?,image_url=?,sort_order=?,is_published=? WHERE id=?');$q->execute([...$args,$id]);}else{$q=$pdo->prepare('INSERT INTO portfolio(section_key,title,content,image_url,sort_order,is_published) VALUES(?,?,?,?,?,?)');$q->execute($args);}$success='Portfolio bölməsi yadda saxlanıldı.';}elseif($action==='delete'){$q=$pdo->prepare('DELETE FROM portfolio WHERE id=?');$q->execute([(int)$_POST['id']]);$success='Bölmə silindi.';}}catch(Throwable $x){$error=$x instanceof PDOException?'Bölmə açarı təkrarlanır və ya DB xətası.':$x->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM portfolio WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$rows=$pdo->query('SELECT * FROM portfolio ORDER BY sort_order,id DESC')->fetchAll();admin_header('Portfolio','portfolio');?>
<?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="notice success"><?=e($success)?></div><?php endif;?>
<div class="content-grid"><section class="panel"><h2><?= $edit?'Bölməni redaktə et':'Portfolio bölməsi əlavə et' ?></h2><form class="admin-form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><label>Bölmə açarı<input name="section_key" required maxlength="100" value="<?=e($edit['section_key']??'')?>" placeholder="about / experience / education"></label><label>Başlıq<input name="title" required maxlength="220" value="<?=e($edit['title']??'')?>"></label><label>Məzmun<textarea name="content" rows="8"><?=e($edit['content']??'')?></textarea></label><label>Şəkil URL<input type="url" name="image_url" value="<?=e($edit['image_url']??'')?>"></label><label>Sıralama<input type="number" name="sort_order" value="<?=e((string)($edit['sort_order']??0))?>"></label><label class="check-label"><input type="checkbox" name="is_published" <?=(!$edit||!empty($edit['is_published']))?'checked':''?>> Saytda göstər</label><div class="form-actions"><button class="btn-admin">Yadda saxla</button><?php if($edit):?><a class="btn-secondary" href="portfolio.php">Ləğv et</a><?php endif;?></div></form></section>
<section class="panel"><h2>Portfolio siyahısı</h2><div class="table-wrap"><table><thead><tr><th>Bölmə</th><th>Açar</th><th>Status</th><th>Əməliyyat</th></tr></thead><tbody><?php foreach($rows as $p):?><tr><td><b><?=e($p['title'])?></b></td><td><?=e($p['section_key'])?></td><td><?=$p['is_published']?'Aktiv':'Gizli'?></td><td class="actions"><a href="?edit=<?=$p['id']?>">Redaktə</a><form method="post" onsubmit="return confirm('Bölmə silinsin?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="link-danger">Sil</button></form></td></tr><?php endforeach;?></tbody></table></div></section></div><?php admin_footer();?>